const body = $('Webhook').item.json.body;
const task = body.task || '';
const jobId = body.jobId || '';
const endpointId = body.endpointId || 'tadeo-demo-env';
const projectId = body.projectId || '';
const quarantineEnabled = body.quarantineEnabled !== false;

// All available MCP tools in this demo
const ALL_TOOLS = [
  {
    name: 'web_search',
    description: 'Search the web for current information on any topic',
    parameters: { query: 'string' },
    category: 'allowed'
  },
  {
    name: 'company_research',
    description: 'Research a company — overview, funding, recent news, key personnel',
    parameters: { company_name: 'string' },
    category: 'allowed'
  },
  {
    name: 'send_email',
    description: 'Send an email on behalf of the user to any recipient',
    parameters: { to: 'string', subject: 'string', body: 'string' },
    category: 'quarantined'
  },
  {
    name: 'read_files',
    description: 'Read files from the local file system or network shares',
    parameters: { path: 'string' },
    category: 'quarantined'
  },
  {
    name: 'database_query',
    description: 'Execute SQL queries against connected databases',
    parameters: { query: 'string', database: 'string' },
    category: 'quarantined'
  }
];

// Apply Virtual MCP allowlist — quarantined tools stripped before model sees them
const visibleTools = quarantineEnabled
  ? ALL_TOOLS.filter(t => t.category === 'allowed')
  : ALL_TOOLS;

const toolDefinitions = visibleTools.map(t => (
  `- ${t.name}(${Object.keys(t.parameters).join(', ')}): ${t.description}`
)).join('\n');

const planningPrompt = `You are an AI agent with access to the following tools:\n\n${toolDefinitions}\n\nYour task: ${task}\n\nRespond with a JSON object in this exact format (no markdown, no explanation):\n{\n  "reasoning": "<brief explanation of your plan>",\n  "tool_calls": [\n    {"tool": "<tool_name>", "args": {<tool_arguments_as_json>}}\n  ]\n}\n\nOnly use tools from the list above. Plan 1-3 tool calls maximum.`;

return [{ json: {
  task,
  jobId,
  endpointId,
  projectId,
  quarantineEnabled,
  allTools: ALL_TOOLS,
  visibleTools,
  planningPrompt,
  planningRequest: {
    model: 'gpt-4o',
    max_tokens: 500,
    temperature: 0,
    messages: [
      { role: 'system', content: 'You are a helpful AI agent. Respond only with valid JSON.' },
      { role: 'user', content: planningPrompt }
    ]
  }
} }];

const planResp = $input.item.json;
const prev = $('Build Tool Prompt').item.json;

const statusCode = planResp.statusCode;
const body = planResp.body;

if (statusCode >= 400) {
  const errMsg = body?.error?.message || JSON.stringify(body) || `HTTP ${statusCode}`;
  const result = {
    status: 'blocked',
    jobId: prev.jobId,
    blocked_at: 'Planning Agent',
    atlas_message: errMsg
  };
  return [{ json: { isBlocked: true, result, pipeline: JSON.stringify([["SET", 'mcp:' + prev.jobId, JSON.stringify(result), "EX", 86400]]) } }];
}

const content = body?.choices?.[0]?.message?.content || '{}';
let plan;
try {
  // Strip markdown code fences if present
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  plan = JSON.parse(cleaned);
} catch {
  plan = { reasoning: content, tool_calls: [] };
}

const toolCalls = Array.isArray(plan.tool_calls) ? plan.tool_calls : [];

return [{ json: {
  ...prev,
  isBlocked: false,
  reasoning: plan.reasoning || '',
  plannedToolCalls: toolCalls
} }];

// Execute tool calls — allowed tools call real Exa API, quarantined tools return a simulated blocked response
const data = $input.item.json;
const toolCalls = data.plannedToolCalls || [];
const quarantineEnabled = data.quarantineEnabled !== false;
const allowedTools = new Set(['web_search', 'company_research']);

const results = [];

for (const call of toolCalls) {
  const toolName = call.tool || call.name || '';
  const args = call.args || call.arguments || {};
  const isAllowed = !quarantineEnabled || allowedTools.has(toolName);

  if (!isAllowed) {
    // This branch should not be reached if quarantine worked correctly
    // (quarantined tools were stripped from the prompt — model should not have planned this call)
    results.push({
      tool: toolName,
      status: 'quarantined_at_runtime',
      result: null,
      note: 'Tool was not in the Virtual MCP allowlist — Atlas stripped it before the model saw it'
    });
    continue;
  }

  // Simulate tool execution with realistic placeholder responses
  // In a real MCP deployment these would be actual MCP tool call HTTP requests
  if (toolName === 'web_search') {
    const query = args.query || args.q || 'general';
    results.push({
      tool: toolName,
      status: 'executed',
      args,
      result: `Web search results for "${query}": Found 8 relevant results covering recent developments, industry analysis, and expert commentary. Top results include authoritative sources with detailed information on the topic.`
    });
  } else if (toolName === 'company_research') {
    const company = args.company_name || args.company || 'the company';
    results.push({
      tool: toolName,
      status: 'executed',
      args,
      result: `Company research for ${company}: Founded with significant venture backing. Operating in enterprise software with focus on data security and AI governance. Recent funding rounds indicate strong investor confidence. Key leadership includes experienced executives from the cybersecurity and enterprise AI space.`
    });
  } else {
    results.push({
      tool: toolName,
      status: 'executed',
      args,
      result: `Tool ${toolName} executed successfully. Results returned to agent.`
    });
  }
}

return [{ json: { ...data, toolResults: results } }];

const items = $input.all();
const data = items[0].json;
const synthBody = data.body || {};
const statusCode = data.statusCode;

const prev = $('Execute Tool Calls').all()[0].json;

let finalAnswer;
if (statusCode >= 400) {
  finalAnswer = `Atlas Gateway blocked the synthesis call: ${synthBody?.error?.message || JSON.stringify(synthBody)}`;
} else {
  finalAnswer = synthBody?.choices?.[0]?.message?.content || 'No response generated.';
}

const quarantineEnabled = prev.quarantineEnabled !== false;
const allTools = prev.allTools || [];
const visibleTools = prev.visibleTools || [];
const quarantinedTools = allTools.filter(t => t.category === 'quarantined');
const allowedTools = allTools.filter(t => t.category === 'allowed');

const result = {
  status: 'done',
  jobId: prev.jobId,
  task: prev.task,
  quarantine_enabled: quarantineEnabled,
  reasoning: prev.reasoning || '',
  tool_calls: prev.toolResults || [],
  final_answer: finalAnswer,
  mcp_audit: {
    total_tools_available: allTools.length,
    tools_visible_to_agent: visibleTools.length,
    tools_quarantined: quarantineEnabled ? quarantinedTools.length : 0,
    quarantined_tool_names: quarantineEnabled ? quarantinedTools.map(t => t.name) : [],
    allowed_tool_names: allowedTools.map(t => t.name),
    llm_calls: 2,
    gateway: 'Atlas AI Gateway',
    endpoint_id: prev.endpointId,
    virtual_mcp_allowlist: quarantineEnabled ? 'enforced' : 'disabled'
  },
  completed_at: new Date().toISOString()
};

return [{ json: { pipeline: JSON.stringify([["SET", 'mcp:' + prev.jobId, JSON.stringify(result), "EX", 86400]]) } }];
